<?php $adminTitle='Quản lý tập';require __DIR__.'/_header.php';$movieId=(int)($_GET['id']??0);$m=movie_by_id($movieId);if(!$m){exit('Không có phim.');}if(isset($_GET['del'])){db()->prepare('DELETE FROM episodes WHERE id=? AND movie_id=?')->execute([(int)$_GET['del'],$movieId]);db()->prepare('UPDATE movies SET episodes_count=(SELECT COUNT(*) FROM episodes WHERE movie_id=?) WHERE id=?')->execute([$movieId,$movieId]);header('Location:episodes.php?id='.$movieId);exit;}if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();db()->prepare('INSERT INTO episodes(movie_id,server_name,season,episode_number,name,stream_url,embed_url) VALUES(?,?,?,?,?,?,?)')->execute([$movieId,trim($_POST['server_name']??'Server 1'),(int)($_POST['season']??1),(int)($_POST['episode_number']??1),trim($_POST['name']??''),trim($_POST['stream_url']??''),trim($_POST['embed_url']??'')]);db()->prepare('UPDATE movies SET episodes_count=(SELECT COUNT(*) FROM episodes WHERE movie_id=?) WHERE id=?')->execute([$movieId,$movieId]);header('Location:episodes.php?id='.$movieId);exit;}$eps=db()->prepare('SELECT * FROM episodes WHERE movie_id=? ORDER BY server_name,season,episode_number,id');$eps->execute([$movieId]);$eps=$eps->fetchAll();?><div class="admin-head"><div><small>EPISODES</small><h1><?=e($m['name'])?></h1><p>Thêm/sửa nguồn phát và tập phim.</p></div><a class="btn" href="movie_edit.php?id=<?=$movieId?>">← Sửa phim</a></div><div class="admin-grid"><section class="admin-card"><h2>Thêm tập</h2><form class="admin-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Server<input name="server_name" value="Server 1"></label><label>Mùa<input type="number" name="season" value="1"></label><label>Số tập<input type="number" name="episode_number" value="1"></label><label>Tên tập<input name="name" placeholder="Tập 1"></label><label>Link M3U8<input name="stream_url"></label><label>Link Embed / iframe<input name="embed_url"></label><button class="btn primary">＋ Thêm tập</button></form></section><section class="admin-card"><h2>Danh sách tập (<?=count($eps)?>)</h2><div style="overflow:auto"><table class="admin-table"><tr><th>Server</th><th>Tập</th><th>Embed</th><th>Hành động</th></tr><?php foreach($eps as $e):?><tr><td><?=e($e['server_name'])?></td><td><?=e($e['name']?:'Tập '.$e['episode_number'])?></td><td><?=e($e['embed_url']?:$e['stream_url'])?></td><td><a class="btn red" onclick="return confirm('Xóa tập?')" href="?id=<?=$movieId?>&del=<?=$e['id']?>">Xóa</a></td></tr><?php endforeach;?></table></div></section></div><?php require __DIR__.'/_footer.php';?>
